from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib, json, re
root = Path('products/distribution/cfib-catalogue-channel')
raw = (root / 'raw/member-savings.html').read_bytes()
source = 'https://www.cfib-fcei.ca/en/member-savings-and-discounts'
class Capture(HTMLParser):
    def __init__(self):
        super().__init__()
        self.href = None
        self.anchor = []
        self.links = []
        self.hidden = None
        self.visible = []
    def handle_starttag(self, tag, attrs):
        if tag in ('style', 'script'):
            self.hidden = tag
        if tag == 'a':
            self.href = dict(attrs).get('href')
            self.anchor = []
    def handle_data(self, data):
        text = ' '.join(data.split())
        if text and not self.hidden:
            self.visible.append(text)
            if self.href:
                self.anchor.append(text)
    def handle_endtag(self, tag):
        if tag == self.hidden:
            self.hidden = None
        if tag == 'a' and self.href:
            url = urljoin(source, self.href)
            label = ' '.join(self.anchor)
            if urlsplit(url).hostname in ('www.cfib-fcei.ca', 'cfib-fcei.ca') and re.search(r'partner|supplier|vendor|benefit|saving|contact', label + ' ' + urlsplit(url).path, re.I):
                record = {'text': label, 'url': url}
                if record not in self.links:
                    self.links.append(record)
            self.href = None
page = Capture()
page.feed(raw.decode('utf-8'))
visible = re.sub(r'\s+', ' ', ' '.join(page.visible))
pattern = re.compile(r'become (?:a |an )?partner|partner with us|supplier|vendor|partnership|offer (?:a |your )?discount', re.I)
contexts = list(dict.fromkeys(visible[max(0, match.start()-100):match.end()+135] for match in pattern.finditer(visible)))
result = {'source': source, 'sha256': hashlib.sha256(raw).hexdigest(), 'first_party_link_pointers': page.links[:40], 'visible_text_excerpts': contexts[:20], 'scope': 'Pointers from one member-savings capture. Confirm any supplier invitation and its conditions in context before drafting an application.'}
output = root / 'director-intake-pointers.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(output), 'links': len(page.links), 'excerpts': len(contexts)}))
